import type { MarkVariant } from './MbaMark'

type Props = {
  variant?: MarkVariant
  layout?: 'horizontal' | 'stacked'
  title?: string
  className?: string
}

/**
 * Full lockup: icon + "MZAB / BUSINESS / ALLIANCE" (wordmark vectorised from the master artwork).
 * Served as static SVGs from /brand (generated by scripts/build-brand-assets.mjs) so the heavy wordmark
 * path is cached once instead of being inlined in every page. Never mirrored in RTL.
 */
export function MbaLogo({ variant = 'color', layout = 'horizontal', title = 'MZAB Business Alliance', className }: Props) {
  const stacked = layout === 'stacked'
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static vector, no optimisation needed
    <img
      src={`/brand/logo-${stacked ? 'stacked-' : ''}${variant}.svg`}
      width={stacked ? 964 : 1896}
      height={stacked ? 1110 : 534}
      alt={title}
      className={className}
      decoding="async"
      draggable={false}
    />
  )
}
